import './style.css';
'use strict';
const $ = id => document.getElementById(id);
let db, drafts = [], orders = [];
const notice = (message, error=false) => { $('notice').textContent=message; $('notice').className=error?'error':''; };
const el = (tag, text, className) => { const node=document.createElement(tag); if(text!==undefined)node.textContent=text; if(className)node.className=className; return node; };
const request = value => new Promise((resolve,reject)=>{value.onsuccess=()=>resolve(value.result);value.onerror=()=>reject(value.error);});
async function init(){try{const open=indexedDB.open('print-reference-desk',1);open.onupgradeneeded=()=>open.result.createObjectStore('orders',{keyPath:'id'});db=await request(open);await refresh();}catch(error){notice('Browser storage is unavailable. Orders cannot be saved here.',true);$('submit').disabled=true;}}
async function refresh(){orders=await request(db.transaction('orders').objectStore('orders').getAll());render();}
function render(){const query=$('search').value.toLowerCase();const all=orders.flatMap(order=>order.variants.map(variant=>({order,variant})));$('count').textContent=`${String(all.length).padStart(2,"0")} REFERENCES`;$('records').replaceChildren();const matches=all.filter(({order,variant})=>[order.customer,order.orderNumber,variant.id,variant.name,variant.destination].join(' ').toLowerCase().includes(query));if(!matches.length){const box=el('div',undefined,'empty');if(!all.length){const sheet=el('div',undefined,'sheet-grid');sheet.setAttribute('aria-hidden','true');for(let i=0;i<24;i++)sheet.append(el('div',i===0?'01':undefined,'slot'));box.append(sheet);}const caption=el('div',undefined,'empty-caption'),copy=el('div');copy.append(el('strong',all.length?'NO MATCHING REFERENCES':'NO ARTWORK YET'),el('p',all.length?'TRY ANOTHER SEARCH.':'UPLOAD CARD FRONTS TO BUILD YOUR REFERENCE LIBRARY.'));caption.append(copy);if(!all.length){const upload=el('button','UPLOAD ARTWORK','secondary');upload.type='button';upload.onclick=()=>$('artwork').click();caption.append(upload);}box.append(caption);$('records').append(box);return;}const grid=el('div',undefined,'cards');for(const {order,variant} of matches){const card=el('article',undefined,'card'),preview=el('div',undefined,'preview'),img=el('img');img.src=variant.image;img.alt=`Artwork: ${variant.name}`;preview.append(img);const details=el('div',undefined,'details');details.append(el('span','REFERENCE READY','ready'),el('h3',variant.name),el('div',variant.id,'ref'),el('p',`${order.customer} · ${order.orderNumber}`),el('p',`${order.widthMm} × ${order.heightMm} mm · ${variant.quantity} cards`),el('p',`Destination: ${variant.destination}`));card.append(preview,details);grid.append(card);}$('records').append(grid);}
function readImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error(`Cannot read ${file.name}`));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error(`Invalid image: ${file.name}`));img.onload=()=>resolve({image:reader.result,pixelWidth:img.naturalWidth,pixelHeight:img.naturalHeight});img.src=reader.result;};reader.readAsDataURL(file);});}
$('artwork').addEventListener('change',async()=>{const files=[...$('artwork').files];if(!files.length)return;$('submit').disabled=true;try{if(files.length+drafts.length>50)throw new Error('An order can contain up to 50 variants.');const incoming=[];for(const file of files){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)throw new Error('Use PNG, JPEG or WebP files up to 10 MB each.');incoming.push({fileName:file.name,mimeType:file.type,...await readImage(file)});}drafts.push(...incoming);renderDrafts();notice(`${incoming.length} artwork image(s) added. Set a name, quantity and destination for each.`);}catch(error){notice(error.message,true);}finally{$('artwork').value='';$('submit').disabled=false;}});
function renderDrafts(){const container=$('drafts');container.replaceChildren();$('art-status').textContent=drafts.length?`${drafts.length} ARTWORK FILE(S)`:'AWAITING ARTWORK';drafts.forEach((draft,index)=>{const box=el('div',undefined,'draft'),img=el('img');img.src=draft.image;img.alt=draft.fileName;box.append(img,el('h3',draft.fileName));for(const [key,title,type,defaultValue] of [['name','Variant / person','text',draft.fileName.replace(/\.[^.]+$/,'')],['quantity','Quantity','number','100'],['destination','Packing / shipping destination','text','']]){const label=el('label',title),input=el('input');input.type=type;input.required=true;input.value=draft[key]??defaultValue;draft[key]=input.value;if(type==='number'){input.min='1';input.max='1000000';input.step='1';}else input.maxLength=250;input.addEventListener('input',()=>draft[key]=input.value);label.append(input);box.append(label);}const remove=el('button','Remove artwork','secondary');remove.type='button';remove.onclick=()=>{drafts.splice(index,1);renderDrafts();};box.append(remove);container.append(box);});}
$('order-form').addEventListener('submit',async event=>{event.preventDefault();if(!drafts.length){notice('Add at least one artwork image.',true);return;}const customer=$('customer').value.trim(),orderNumber=$('order-number').value.trim();if(!customer||!orderNumber||drafts.some(v=>!v.name.trim()||!v.destination.trim()||!Number.isInteger(Number(v.quantity))||Number(v.quantity)<1)){notice('Complete the customer, order number and each variant’s name, quantity and destination.',true);return;}if(orders.some(o=>o.orderNumber.toLowerCase()===orderNumber.toLowerCase())){notice('That order number already exists. Use a unique order number.',true);return;}$('submit').disabled=true;try{const id=crypto.randomUUID();const order={id,orderNumber,customer,widthMm:Number($('width').value),heightMm:Number($('height').value),createdAt:new Date().toISOString(),variants:drafts.map(v=>({...v,id:crypto.randomUUID(),name:v.name.trim(),destination:v.destination.trim(),quantity:Number(v.quantity),side:'front',status:'reference-ready'}))};await new Promise((resolve,reject)=>{const tx=db.transaction('orders','readwrite');tx.objectStore('orders').add(order);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});drafts=[];$('order-form').reset();renderDrafts();await refresh();notice(`Order ${orderNumber} saved with ${order.variants.length} scanning reference(s).`);}catch(error){notice('Could not save this order. Browser storage may be full. Your draft is still available.',true);}finally{$('submit').disabled=false;}});
$('search').addEventListener('input',render);
$('export').addEventListener('click',()=>{if(!orders.length){notice('Create an order before exporting.');return;}const catalog={schemaVersion:1,exportedAt:new Date().toISOString(),imageEncoding:'data-url',orders};const blob=new Blob([JSON.stringify(catalog,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=el('a');link.href=url;link.download=`print-scan-catalog-${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Catalog exported with original images, dimensions, IDs and destinations.');});
init();

// The 24-slot empty grid is a visual placeholder, not a production imposition.
document.querySelectorAll('.select-artwork').forEach(button=>button.onclick=()=>$('artwork').click());
for(const id of ['width','height']) $(id).addEventListener('input',()=>{$('trim-summary').textContent=`${$('width').value} × ${$('height').value} MM`;});
const dropZone=$('drop-zone');
for(const name of ['dragenter','dragover'])dropZone.addEventListener(name,event=>{event.preventDefault();dropZone.classList.add('dragging');});
for(const name of ['dragleave','drop'])dropZone.addEventListener(name,event=>{event.preventDefault();dropZone.classList.remove('dragging');});
dropZone.addEventListener('drop',event=>{if(event.dataTransfer.files.length){$('artwork').files=event.dataTransfer.files;$('artwork').dispatchEvent(new Event('change'));}});

